sys_script_include.script:
var switchTrades = Class.create();
switchTrades.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    getTrades: function() {
        var filters = this.getParameter('sysparm_filters') || '{}';
        try {
            filters = JSON.parse(filters);
        } catch (e) {
            filters = {};
        }

        var table = 'incident'; // <-- change to your trade table
        var gr = new GlideRecord(table);

        // Example dynamic filters (change fields to match your schema)
        if (filters.caller)
            gr.addQuery('u_caller', filters.caller); // replace 'u_caller' if needed
        if (filters.category)
            gr.addQuery('category', filters.category);
        if (filters.state)
            gr.addQuery('state', filters.state);

        // You can add more logic here (active = true, search keywords, etc.)
        gr.orderByDesc('sys_created_on');
        gr.setLimit(200);
        gr.query();

        var out = [];
        while (gr.next()) {
            out.push({
                sys_id: gr.getValue('sys_id'),
                display: gr.getDisplayValue() // display value shown in list
            });
        }
        return JSON.stringify(out); // GlideAjax will expose this in responseXML.answer
    },


    getMatchinRecords: function() {


        var filters = this.getParameter('sysparm_filters') || '{}';

    },


    getRecords: function() {
        var records = [];
        // Replace 'incident' with your desired table name (e.g., 'alm_asset')
        var gr = new GlideRecord('incident');
        // Add any necessary query conditions here
        gr.addActiveQuery();
        gr.query();

        while (gr.next()) {
            records.push({
                sys_id: gr.getUniqueValue(),
                // Replace 'number' with the field(s) you want to display
                display_value: gr.getValue('number') + ' - ' + gr.getValue('short_description')
            });
        }
        // Return the array as a JSON string
        return JSON.stringify(records);
    },


	getUserId: function(){
		var userIDArr = [];
		var getGroup = this.getParameter('sysparm_group');
		var getUser = new GlideRecord('sys_user_grmember');
		getUser.addEncodedQuery('group='+getGroup);
		getUser.query();
		while(getUser.next()){
			userIDArr.push(getUser.getValue('user'));
		}
		return userIDArr.join(',')
	},





    type: 'switchTrades'
});
